		/** 
		 * Tests creating a new DataSet.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a DataSet");

			StringBuilder msg = new StringBuilder( "-- Failed to create a DataSet" );

			try {            
				DataSet entity = DataSetService.getDataSetInstance().createDataSet( generateNewEntity() );
				thePrimaryKey = entity.getDataSetId();
				LOGGER.info( "-- Successfully created a DataSet with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a DataSet. 
		 */
		public DataSet testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created DataSet" );

			DataSet entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read DataSet with primary key" );
			msg.append( thePrimaryKey );
			
			DataSetFetchOneSummary fetchOneSummary = new DataSetFetchOneSummary( thePrimaryKey );

			try {
				entity = DataSetService.getDataSetInstance().getDataSet( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found DataSet " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a DataSet.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a DataSet." );

			StringBuilder msg = new StringBuilder( "Failed to update a DataSet : " );        
			DataSet entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created DataSet." );

				// for use later on...
				thePrimaryKey = entity.getDataSetId();

				DataSetService proxy = DataSetService.getDataSetInstance();            
				proxy.updateDataSet( entity );   

				LOGGER.info( "-- Successfully saved DataSet - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a DataSet.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created DataSet." );

			try{
			    DataSet entity = testRead(); 
				DataSetService.getDataSetInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted DataSet with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete DataSet with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all DataSets.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of DataSets:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all DataSet : " );        
			List<DataSet> collection  = null;

			try {
				// call the static get method on the DataSetService
				collection = DataSetService.getDataSetInstance().getAllDataSet();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					DataSet entity = null;            
					Iterator<DataSet> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getDataSetId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

